#!/bin/bash
set -eu
src="$1"
dst="$2/Contents/Frameworks/Chromium Embedded Framework.framework"
mkdir -p "$dst/Versions/A"
/usr/bin/ditto "$src/Chromium Embedded Framework.framework" "$dst/Versions/A"
# -n avoids following existing directory links on incremental builds.
ln -sfn 'Versions/A/Chromium Embedded Framework' "$dst/Chromium Embedded Framework"
ln -sfn 'Versions/A/Libraries' "$dst/Libraries"
ln -sfn 'Versions/A/Resources' "$dst/Resources"
ln -sfn A "$dst/Versions/Current"
# Remove only the erroneous self-link generated by the upstream macro on older builds.
for link in "$dst/Versions/A/A" "$dst/Versions/A/Libraries/Libraries" "$dst/Versions/A/Resources/Resources"; do
 if [ -L "$link" ]; then unlink "$link"; fi
done
